import json
S=lambda key,label,tag,prompt,ans,model,why,ok=None:{"key":key,"label":label,"tag":tag,"kind":"sentence","prompt":prompt,"ans":ans,**({"ok":ok} if ok else {}),"model":model,"why":why}
def C(key,label,tag,prompt,options,ans,*r):
    model,why=r if len(r)==2 else (ans,r[0])
    return {"key":key,"label":label,"tag":tag,"kind":"choice","prompt":prompt,"options":options,"ans":ans,"model":model,"why":why}
T=lambda key,label,tag,prompt,accept,model,why:{"key":key,"label":label,"tag":tag,"kind":"text","prompt":prompt,"accept":accept,"model":model,"why":why}
